   const initial=freshState();storeRef.current=createStore(initial);storeRef.current.replace(initial);
   setProfile(blankProfile);setHistoryWorkout(null);setEditingHistory(false);setExercise(null);setInspectSession(null);setProposalView(null);setFeedback(false);setFocusedExercise(null);closeBuilder();setVaultOpen(false);setEncryptedSaved(false);setStorageError('');setStorageConflict(false);setStorageBlocked(false);setEntry(true);setReset(false);setTab('Today');
